WITH r AS (SELECT src, dst FROM relations_at('ecosystem-ac', TIMESTAMP '2018-05-13 08:44') WHERE rel = 'relates_to')
SELECT DISTINCT CASE WHEN src = 'issue:ACDEV-307' THEN dst ELSE src END AS linked
FROM r WHERE (src = 'issue:ACDEV-307' OR dst = 'issue:ACDEV-307') AND NOT (src = 'issue:AC-685' OR dst = 'issue:AC-685');

